const start = Temporal.Instant.fromEpochMilliseconds(86_400_000);
const later = start.add({ minutes: 90 });

console.log(start.toString());
console.log(later.epochMilliseconds - start.epochMilliseconds);
console.log(later.toZonedDateTimeISO("Asia/Kolkata").hour);
console.log(later.day);
